export function getCompactListingReference(): string {
  const lines: string[] = [];
  for (const [model, listings] of Object.entries(HYGGLO_LISTING_INDEX)) {
    if (listings.length > 1) {
      lines.push(`${model.toUpperCase()} (${listings.length} listings): ${listings.slice(0, 3).join(' | ')}`);
    }
  }
  return lines.join('\n');
}
